$_MODULE['<{lggooglereviews}prestashop>help_3612879708f67ddbaffef6b85b8a7721'] = 'No campo \"Comentários a mostrar\" pode escolher o número de blocos a mostrar simultaneamente no selector';
$_MODULE['<{lggooglereviews}prestashop>help_a8a22f09149459a347b30e8005ab34f4'] = '\"Rich Snippets\" são um conjunto de etiquetas que não são visíveis para os seus clientes, mas que são utilizadas pelos motores de busca para recolher informações a partir das suas opiniões. Se quiser facilitar aos motores de busca a obtenção desta informação, verifique \"Sim\".';
$_MODULE['<{lggooglereviews}prestashop>help_dee2ff8dd3e1feec8bb332b79163a1a4'] = '\"Mostrar cabeçalho\" incluirá no início do bloco um cabeçalho onde poderá mostrar os seus dados comerciais tais como: o nome, a imagem, as classificações e os links para o seu perfil no Google Places';
$_MODULE['<{lggooglereviews}prestashop>help_554d5ff6ac027319ca16bf76c83c6095'] = '\"Mostrar imagem de cabeçalho\" incluirá a imagem associada à sua empresa se a tiver carregado e, caso contrário, o ícone predefinido que definiu no Google My Business';
