$_MODULE['<{lggooglereviews}prestashop>help_ee27a2fa1a14965f274765a67e5a8924'] = '\"Mostrar link para [Ver todas as críticas]\" mostrará um link onde os seus clientes podem aceder à sua lista completa de críticas no Google My Business';
$_MODULE['<{lggooglereviews}prestashop>help_559358899352d23a924ba8782fd364dc'] = '\"Mostrar link para [Adicionar Análise]\" mostrará um link para convidar os seus clientes a deixar uma análise do seu negócio';
$_MODULE['<{lggooglereviews}prestashop>help_1ef8624b78f3fd5b154773974b2f2dac'] = 'Se tiver seleccionado a opção anterior, deve incluir a url de convite. Na secção \"Pedir Revisões\" da ajuda, explicamos como obtê-lo';
