$_MODULE['<{lggooglereviews}prestashop>help_a481969fefacd2cac4651bc0cad8ace8'] = 'Indicar se pretende mostrar um link para o perfil dos utilizadores que deixaram as suas críticas';
$_MODULE['<{lggooglereviews}prestashop>help_4e7c6bc487018fc97dc555c507a10cc0'] = 'Reveja os seus dados comerciais';
