$_MODULE['<{lggooglereviews}prestashop>help_b1e986d1a578a5ff89bedf9d5e52b012'] = 'Para utilizar as APIs do Google Maps e Places, é necessário registar a aplicação e obter uma chave API. Provavelmente, já sabe, mas nós explicamos como obter esta chave se não souber.';
$_MODULE['<{lggooglereviews}prestashop>help_929457b0d047a741db5a051fb3409dab'] = 'Como criar a sua chave da API do Google Maps';
$_MODULE['<{lggooglereviews}prestashop>help_9620b9481e88199f573c9800e8f2a621'] = 'Siga as instruções abaixo para criar uma CHAVE API.';
$_MODULE['<{lggooglereviews}prestashop>help_45887556e1cc6a572c574708e1676ea6'] = 'Deve iniciar sessão com a sua conta de gmail ou criar uma nova conta de gmail que deseja associar ao seu projecto.';
$_MODULE['<{lggooglereviews}prestashop>help_b4c1815fa181e8d36cba075fb5ea51b8'] = 'Uma vez conectado, deverá ir para a consola da plataforma Google Cloud Platform:';
$_MODULE['<{lggooglereviews}prestashop>help_6b05e59b1c6f2513ea4ec8811602146c'] = 'No menu do lado esquerdo, irá para a secção APIS e Serviços.';
$_MODULE['<{lggooglereviews}prestashop>help_7622adcc5af6e55d3a7667c19c13a6fb'] = 'Escrever o nome do projecto e clicar no botão \"CRIAR\".';
$_MODULE['<{lggooglereviews}prestashop>help_55fd75e5be5f25af27c8e67eb2faa100'] = 'Em seguida, clicaremos no botão \"ENABLE APIS AND SERVICES\".';
$_MODULE['<{lggooglereviews}prestashop>help_fc45981f4bf623a93720e128bc1a1c10'] = 'Para este caso, seleccionar \"LOCALIZAÇÕES API\".';
$_MODULE['<{lggooglereviews}prestashop>help_7684dbca91a174e239e2a8d062df29b1'] = 'Clicar no botão \"ENABLE\".';
$_MODULE['<{lggooglereviews}prestashop>help_824a6c6060cae1ce4265e018736337df'] = 'Uma vez criada a API, no separador \"Credentials\" (Credenciais). Aí, clicar no link \"Credenciais em APIs e serviços\".';
$_MODULE['<{lggooglereviews}prestashop>help_04ee3b1cdc9f4b27e27ec84255924905'] = 'Copiar a chave API que é mostrada no ecrã, porque vamos precisar dela mais tarde.';
$_MODULE['<{lggooglereviews}prestashop>help_ebc72db384475b19cabb579e57785996'] = 'Verá que, nessa mesma janela pop-up, lhe dá a opção de \"Restringir palavra-passe\". Clique nesse link se quiser que essa chave seja utilizada apenas num determinado domínio, por exemplo.';
$_MODULE['<{lggooglereviews}prestashop>help_449abc375ecc691847413fbc9d739a59'] = 'Assim que tiver restringido a palavra-passe, se o desejar, teremos de introduzir a informação de facturação porque, caso contrário, só nos será permitido ligar para esta API uma vez por dia e, sinceramente, espero que o seu website tenha mais do que uma visita por dia. Isto não significa que nos vai ser cobrado nada, uma vez que o Google oferece-lhe este serviço gratuitamente para um grande número de chamadas para a API, um número pelo qual uma empresa PME normalmente não terá de pagar. Se exceder o número de visualizações que o Google lhe dá gratuitamente, é provável que o negócio esteja a correr muito, muito bem e que não tenha problemas em investir um pouco nisto. Mesmo que não o ultrapasse, o Google pede-lhe a sua informação de facturação no caso de isso acontecer em algum momento. Por outro lado, para sua paz de espírito, digo-lhe que o Google lhe permite colocar um limite de chamadas à sua API por mês. Portanto, pode limitar o número de chamadas gratuitas por mês e, assim, nunca lhe será cobrado; simplesmente, as opiniões serão interrompidas se exceder esse número.';
$_MODULE['<{lggooglereviews}prestashop>help_fb9ad09694f5986566d455aca68450a9'] = 'Como introduzir as informações de facturação?';
$_MODULE['<{lggooglereviews}prestashop>help_719545827e174b52f5007290935e39e1'] = 'Siga as instruções abaixo para introduzir as suas informações de facturação.';
$_MODULE['<{lggooglereviews}prestashop>help_78a42223fc0bf73ebd95dea4c186874f'] = 'Na consola da plataforma Google Cloud, se clicarmos no ícone do menu com 3 linhas horizontais, que se encontra na extrema esquerda, aparecerá o menu de navegação. Aí, devemos clicar no item \"Facturação\".';
$_MODULE['<{lggooglereviews}prestashop>help_17bdf9283a5ae0b5df854db1dd3dd7c9'] = 'Clicaremos no botão \"Gerir contas de facturação\".';
$_MODULE['<{lggooglereviews}prestashop>help_d854108423e34b73cf5b3537c4e74e69'] = 'Clicaremos no botão \"Adicionar conta de facturação\" e seguiremos os passos indicados pelo Google, introduzindo as informações solicitadas.';
$_MODULE['<{lggooglereviews}prestashop>help_b04a7d3f4f74a068e64d49e24b110c76'] = 'Seleccionar o perfil de pagamentos do Google que será associado a esta conta de facturação. Pode seleccionar um perfil existente ou criar um novo perfil.';
$_MODULE['<{lggooglereviews}prestashop>help_a800cf67d7ea062c818c5e9ee0f661a2'] = 'Finalmente, no projecto que está a configurar, temos de permitir a facturação desse projecto. Fá-lo-emos em \"Facturação\", clicando em \"Ligar conta de facturação\". Seleccionaremos a conta e clicaremos em \"Estabelecer conta\".';
